"""Printing chat cells — handwritten, not generated by Speakeasy.

A `Cell` (`textql_sdk._connect.public.chat_pb2.Cell`) is a oneof over ~50 payload
types. This module prints one the way the v2 SSE stream
(`POST /v2/chats/stream`) presents it: a flat event log where an execution step
appears **twice** — once when it starts running, carrying the query or code the
model generated, and once when it finishes, carrying the result.

    cell  sql 4f2a91c8-…  running
          SELECT customer, sum(amount) AS revenue FROM orders GROUP BY 1
    cell  sql 4f2a91c8-…  done  842ms
          12 rows × 2 cols
          | customer | revenue |
          | Acme     |    1200 |
    text  Acme led at $12,000.
    done  completed

Usage over the streaming bridge:

    from textql_sdk.cell_render import CellPrinter

    printer = CellPrinter()
    async for event in streaming.chats.watch_chat(request):
        if event.WhichOneof("payload") == "cell":
            printer.cell(event.cell)

`watch_chat` re-sends a full snapshot of a cell on every update, so `CellPrinter`
collapses those to the two moments above; it never reprints a cell it has
already shown in the same state.

Prose is the exception: it is appended as it arrives rather than held back until
`complete`, so the answer types itself out. See :func:`cell_prose`.

`CELL_INPUTS` names the input fields per cell type, and everything else the
server set is printed directly off the protobuf descriptors — so a cell type this
module has never heard of still shows its contents. The registries are plain
module-level dicts; reassign them to change what a type looks like.
"""

from __future__ import annotations

from typing import Any, Optional

from google.protobuf.descriptor import FieldDescriptor

from textql_sdk._connect.public import chat_pb2

__all__ = [
    "CellPrinter",
    "cell_lines",
    "cell_kind",
    "cell_prose",
    "cell_state",
    "CELL_KINDS",
    "CELL_INPUTS",
    "PROSE_CELLS",
    "HIDDEN_FIELDS",
    "FIELD_LABELS",
    "NEVER_INLINE",
]

# Short labels where stripping the `_cell` suffix reads badly.
CELL_KINDS = {
    "py_cell": "python",
    "md_cell": "markdown",
    "ans_cell": "answer",
    "ws_cell": "web_search",
    "mcp_tool_cell": "mcp",
    "powerbi_dax_cell": "dax",
}

# Conversational cells print as the v2 stream's `text` event. The value is the
# field the text lives in — it is not `content` everywhere.
PROSE_CELLS = {
    "md_cell": "content",
    "ans_cell": "content",
    "summary_cell": "summary",
}

# The fields the model *asked* for, per cell type; printed on the `running`
# line. Everything else the server set is the result, printed on `done`.
CELL_INPUTS = {
    "sql_cell": ("query", "connector_id"),
    "tableau_sql_cell": ("query",),
    "py_cell": ("code",),
    "bash_cell": ("script",),
    "javascript_cell": ("code", "title"),
    "streamlit_cell": ("code",),
    "dashboard_cell": ("action", "name", "code"),
    "app_cell": ("action", "name"),
    "powerbi_dax_cell": ("dax_query", "dataset_id"),
    "metrics_cell": ("query", "dataset", "ontology_id"),
    "ontology_query_cell": ("action", "path", "params_json", "connector_id"),
    "ws_cell": ("query", "search_type", "date_range"),
    "linkedin_search_cell": ("query",),
    "mcp_tool_cell": ("server_name", "tool_name", "arguments_json"),
    "use_skill_cell": ("trigger",),
    "subagent_cell": ("objective", "subagent_name"),
    "ontology_search_metrics_cell": ("query", "ontology_id"),
    "ontology_open_object_cell": ("requested_object", "ontology_id"),
    "list_apps_cell": ("search_term",),
    "email_cell": ("to", "subject", "body"),
    "preview_cell": ("target", "preview_type", "name"),
}
DEFAULT_INPUTS = ("query", "code", "script")

# Never printed: HTML mirrors of text already shown, structural payloads, and
# the timing that goes on the status line instead.
HIDDEN_FIELDS = frozenset({
    "rendered_html",
    "html_preview",
    "rendered_body_html",
    "blocks",
    "citations",
    "synthetic_tool_use_id",
    "execution_time_ms",
})

# Shorter labels for fields whose proto name reads badly.
FIELD_LABELS = {
    "dataframe_preview": "preview",
    "output": "stdout",
    "dataframe_info": "dataframes",
    "arguments_json": "args",
    "params_json": "params",
    "content_json": "result",
    "exa_results": "results",
    "declared_params": "params",
}

# The point of the cell rather than metadata about it: always its own block,
# never folded onto the head line however short it happens to be.
NEVER_INLINE = frozenset({
    "query", "code", "script", "sql", "dax_query", "content", "body", "stdout",
    "stderr", "output", "answer", "summary", "description", "objective",
    "dataframe_preview", "final_message", "email_summary", "event_summary",
})

LABEL_WIDTH = 6  # "cell  ", "text  ", "done  "
INDENT = " " * LABEL_WIDTH


def cell_kind(cell: Any) -> str:
    """Short name for a cell's payload type, e.g. `sql`, `python`, `markdown`."""
    kind = cell.WhichOneof("value")
    if kind is None:
        return "empty"
    return CELL_KINDS.get(kind, str(kind).removesuffix("_cell"))


def cell_prose(cell: Any) -> Optional[tuple[str, str]]:
    """`(label, text)` for a conversational cell, or `None` if it isn't one.

    Prose is written a token at a time: the stream re-sends the cell with a
    longer `content` every few hundred milliseconds, `complete` staying false
    the whole way. Waiting for `complete` therefore turns a message that took
    six seconds to write into one block that appears at the end, so
    `CellPrinter` renders the new suffix on every snapshot instead. The FE does
    the same thing the other way round — it replaces the cell and lets Svelte
    repaint, which a terminal can't do.

    Adding a cell type to `PROSE_CELLS` therefore asserts more than "render this
    bare": it asserts the field only ever grows. That does not hold for fields
    the server re-derives per snapshot, so `CellPrinter` verifies it rather than
    trusting it — see `CellPrinter._prose`.
    """
    kind = cell.WhichOneof("value")
    field = PROSE_CELLS.get(kind)
    if field is None:
        return None
    payload = getattr(cell, kind)
    if field not in payload.DESCRIPTOR.fields_by_name:
        return None
    # v2 calls the assistant's prose `text`; a human turn is not one of its
    # events at all, so label it rather than blur the two together.
    return ("text" if cell.generated else "you"), (getattr(payload, field) or "")


def cell_state(cell: Any) -> str:
    """`running`, `done`, `halted`, or `failed: …` for a cell snapshot.

    `complete` is the terminal signal, not `lifecycle`: it is polymorphic
    server-side, so a markdown cell is complete on creation while a SQL cell is
    only complete once executed. `exec_error` is per cell and is not covered by
    the stream's `run_error` event.
    """
    # pylint: disable=no-member
    # chat_pb2 builds LIFECYCLE_HALTED at import time, so pylint can't see it;
    # pyright, which gates CI, resolves it fine.
    if cell.exec_error:
        return f"failed: {cell.exec_error.splitlines()[0]}"
    if cell.lifecycle == chat_pb2.LIFECYCLE_HALTED:
        return "halted"
    return "done" if cell.complete else "running"


# ── printing protobuf values ──────────────────────────────────────────────────


def _scalar_text(field: FieldDescriptor, value: Any) -> str:
    if field.type == FieldDescriptor.TYPE_ENUM and field.enum_type is not None:
        return field.enum_type.values_by_number[value].name.lower()
    if isinstance(value, bool):
        return "yes" if value else "no"
    return str(value)


def _message_summary(msg: Any) -> str:
    """One line for a nested message — enough to know what it is."""
    name = msg.DESCRIPTOR.full_name
    if name == "google.protobuf.Timestamp":
        return msg.ToDatetime().isoformat()
    if name == "textql.rpc.public.dataframe.DataFrameWithInfo":
        return _message_summary(msg.info)
    if name == "textql.rpc.public.dataframe.DataFrameInfo":
        shape = f"{msg.num_rows} rows × {msg.num_cols} cols"
        return f"{shape} ({msg.name})" if msg.name else shape

    set_fields = msg.ListFields()
    # Prefer the fields a human identifies the thing by, then fall back to
    # whatever it happens to carry.
    named = {f.name: v for f, v in set_fields}
    for key in ("name", "title", "subject", "file_name", "tool_name", "query"):
        if named.get(key):
            url = named.get("url") or named.get("html_url") or named.get("web_view_link")
            return f"{named[key]} — {url}" if url else str(named[key])
    if named.get("url"):
        return str(named["url"])
    parts = [
        f"{f.name}={_scalar_text(f, v)}"
        for f, v in set_fields
        if f.type != FieldDescriptor.TYPE_MESSAGE and not f.is_repeated
    ]
    return " ".join(parts[:3]) or f"({msg.DESCRIPTOR.name})"


def _field_lines(field: FieldDescriptor, value: Any, bare: bool) -> list[str]:
    """Lines for one field. `bare` drops the label (the field stands alone)."""
    label = FIELD_LABELS.get(field.name, field.name.replace("_", " "))

    if field.is_repeated:
        if field.type == FieldDescriptor.TYPE_MESSAGE:
            rows = (f"  {_message_summary(item)}" for item in value)
            return [f"{label} ({len(value)})", *rows]
        if field.type == FieldDescriptor.TYPE_STRING:
            # Repeated strings are chunked text (stdout, previews) — join them.
            lines = "\n".join(value).rstrip().splitlines()
            return lines if bare else [f"{label}:", *lines]
        return [f"{label}: {', '.join(_scalar_text(field, v) for v in value)}"]

    if field.type == FieldDescriptor.TYPE_MESSAGE:
        return [f"{label}: {_message_summary(value)}"]

    lines = _scalar_text(field, value).rstrip().splitlines()
    if bare:
        return lines
    if len(lines) == 1:
        return [f"{label}: {lines[0]}"]
    return [f"{label}:", *lines]


def _auth_hold(payload: Any) -> Optional[str]:
    """Cells park on `auth_required` waiting for a per-member connector login."""
    if "auth_required" not in {f.name for f in payload.DESCRIPTOR.fields}:
        return None
    if not payload.auth_required or getattr(payload, "auth_completed", False):
        return None
    who = getattr(payload, "auth_connector_name", "") or getattr(
        payload, "auth_provider_name", ""
    )
    return f"auth required{f': {who}' if who else ''} — approve it in the app"


def _split(fields: list[tuple[FieldDescriptor, Any]]) -> tuple[str, list[str]]:
    """Short scalars go on the head line; text and lists go in the body."""
    head, body_fields = [], []
    for field, value in fields:
        text = (
            "" if field.type == FieldDescriptor.TYPE_MESSAGE
            else _scalar_text(field, value)
        )
        inline = (
            text
            and field.name not in NEVER_INLINE
            and not field.is_repeated
            and "\n" not in text
            and len(text) <= 40
        )
        if inline:
            head.append(f"{field.name}={text}")
        else:
            body_fields.append((field, value))

    body: list[str] = []
    for field, value in body_fields:
        body.extend(_field_lines(field, value, bare=len(body_fields) == 1))
    return ("  " + "  ".join(head) if head else ""), body


def _reflow(text: str) -> str:
    """Lay prose out under its label: continuation lines indented by `INDENT`,
    trailing whitespace dropped from every line that has ended.

    Shared by the block and streaming paths so the layout rule lives once. When
    streaming, `text` is a chunk rather than the whole message, so the first
    line continues whatever is already on screen and the last is still being
    written — neither gets rstripped.
    """
    head, *rest = text.split("\n")
    if not rest:
        return head
    *finished, tail = rest
    return "\n".join(
        [head.rstrip(), *((INDENT + line).rstrip() for line in finished), INDENT + tail]
    )


def _duration(cell: Any, payload: Any) -> str:
    ms = getattr(payload, "execution_time_ms", 0) or (
        cell.duration_ms if cell.HasField("duration_ms") else 0
    )
    if not ms:
        return ""
    return f"  {ms / 1000:.1f}s" if ms >= 1000 else f"  {ms}ms"


def cell_lines(cell: Any, done: bool) -> list[str]:
    """Print-ready lines for one cell, as the `running` or `done` event.

    `done=False` shows the input the model generated; `done=True` shows the
    result. Returns an empty list when there is nothing to show.
    """
    kind = cell.WhichOneof("value")
    if kind is None:
        return [f"cell  empty {cell.id}"]
    payload = getattr(cell, kind)

    # A completed thinking cell with no content only exists so the backend can
    # replay the signed reasoning block — there's nothing to show.
    if kind == "thinking_cell" and not payload.content:
        return []

    prose = cell_prose(cell)
    if prose is not None:
        if not done:
            return []
        label, text = prose
        return f"{label:<{LABEL_WIDTH}}{_reflow(text.strip() or '(empty)')}".splitlines()

    input_names = CELL_INPUTS.get(kind, DEFAULT_INPUTS)
    present = {f.name: (f, v) for f, v in payload.ListFields()}
    if done:
        fields = [
            (f, v)
            for name, (f, v) in present.items()
            if name not in input_names
            and name not in HIDDEN_FIELDS
            and not name.startswith("auth_")
        ]
        status = f"{cell_state(cell)}{_duration(cell, payload)}"
    else:
        fields = [present[name] for name in input_names if name in present]
        status = "running"

    tags, body = _split(fields)
    hold = _auth_hold(payload)
    if hold:
        body.append(hold)
    head = f"cell  {cell_kind(cell)} {cell.id}  {status}{tags}"
    return [head, *((INDENT + line).rstrip() for line in body)]


class CellPrinter:
    """Prints each cell twice: when it starts running, and when it finishes.

    `watch_chat` re-sends a full snapshot on every update — while a query is
    still being written, while it executes, and once more when it settles. This
    collapses that to the two events the v2 stream emits, so a run reads as a
    flat log instead of the same cell scrolling past a dozen times.

    Prose is the exception. Those snapshots carry a *longer* message rather than
    a further-along cell, so they're written out as they land — the message
    types itself instead of appearing all at once when the cell completes. See
    :func:`cell_prose`.
    """

    def __init__(self) -> None:
        self.latest: dict[str, Any] = {}
        self.shown: set[tuple[str, bool]] = set()
        # Prose cell holding the cursor mid-line, and how much of each cell's
        # text has already gone out.
        self._open: Optional[str] = None
        self._written: dict[str, str] = {}

    def note(self, event: str, text: str = "") -> None:
        """Print a run-level line, lined up with the cell bodies."""
        self._close()
        print(f"{event:<{LABEL_WIDTH}}{text}".rstrip(), flush=True)

    def cell(self, cell: Any) -> None:
        """Print one `cell` event from the stream, if it says anything new."""
        # pylint: disable=no-member
        # chat_pb2 builds LIFECYCLE_EXECUTING at import time; pyright resolves it.
        self.latest[cell.id] = cell
        prose = cell_prose(cell)
        if prose is not None:
            self._prose(cell, *prose)
            return
        if cell.lifecycle >= chat_pb2.LIFECYCLE_EXECUTING:
            # Only now is the generated query or code final. Cells that never
            # execute (markdown, documents) skip straight to the done event.
            self._emit(cell, done=False)
        if cell.complete:
            self._emit(cell, done=True)

    def _prose(self, cell: Any, label: str, text: str) -> None:
        """Append whatever this snapshot added to a message already in flight."""
        if (cell.id, True) in self.shown:
            return
        # Not every prose field is strictly append-only: the server re-derives
        # markdown content per snapshot (it collapses runs of `<br>`), which can
        # shorten it. Splicing at a stale offset would garble the line, so when
        # the new text isn't an extension of what's on screen, restart the line
        # with the whole corrected message.
        printed = self._written.get(cell.id, "")
        resumable = text.startswith(printed)
        if self._open != cell.id or not resumable:
            if not text.strip() and not cell.complete:
                return  # nothing said yet — don't open a bare label line
            # Another cell printed in between, or the text was rewritten, so
            # re-label. Mid-message that reads as a continuation, not a repeat.
            self._close()
            print(f"{label:<{LABEL_WIDTH}}", end="", flush=True)
            self._open = cell.id
            if not resumable:
                printed = ""
        delta = text[len(printed):]
        if not printed:
            delta = delta.lstrip()  # would otherwise land right after the label
        self._written[cell.id] = text
        print(_reflow(delta), end="", flush=True)
        if cell.complete:
            if not text.strip():
                print("(empty)", end="")
            self.shown.add((cell.id, True))
            self._close()

    def _close(self) -> None:
        """End the line a streaming prose cell left open."""
        if self._open is not None:
            self._open = None
            print(flush=True)

    def _emit(self, cell: Any, done: bool) -> None:
        if (cell.id, done) in self.shown:
            return
        try:
            lines = cell_lines(cell, done)
        except Exception as exc:  # pylint: disable=broad-except
            # A printing bug must not tear down a live run.
            lines = [f"cell  {cell.id}  print failed: {exc!r}"]
        self.shown.add((cell.id, done))
        if lines:
            self._close()  # don't land on the end of a half-written message
            print("\n".join(lines), flush=True)

    def flush(self) -> None:
        """Print cells that never reached a terminal state."""
        self._close()
        for cell in self.latest.values():
            # Prose already had everything the stream delivered written out as
            # it arrived; reprinting it as a block would duplicate it.
            if cell_prose(cell) is None:
                self._emit(cell, done=True)

    def failed(self) -> list[str]:
        """IDs of cells that reported `exec_error` — not covered by `run_error`."""
        return [c.id for c in self.latest.values() if c.exec_error]

    def unfinished(self) -> list[str]:
        """IDs of cells that never reported `complete`."""
        return [c.id for c in self.latest.values() if not c.complete]
